"""Training data for pass selection, generated by running the real compiler.

**Learning problem.** Given the current IR module (as a feature vector), choose
the next pass, or *stop*. A state's **label** is obtained by actually applying
*every* pass to a copy of the module and measuring the resulting cost:

    label(state) = argmin_pass cost(pass(state))   if that improves on cost(state)
                   "stop"                            otherwise

No label is invented: every number comes from compiling and executing. The
cost is the IR interpreter's metric (``cost`` = weighted, or ``steps``). Which
one is used is a configuration choice that EXP-002 informs.

**Trajectories.** Starting from the unoptimized SSA IR, a state sequence is
produced by an epsilon-greedy walk: with probability ``epsilon`` take a random
pass, otherwise the best one. The *oracle-greedy* part makes the recorded
states resemble those a good scheduler would visit. The random part adds
states a learned policy might reach after a mistake. Every pass is evaluated
at every recorded state, so each record contains the complete one-step
outcome table, not just the action taken.

**Cost and caching.** Each evaluation is an interpreter run. States repeat
often, because many passes are no-ops in a given state, so costs are memoized
by a hash of the printed IR.
"""

from __future__ import annotations

import hashlib
import random
from collections.abc import Callable
from dataclasses import asdict, dataclass

from forgecompile.driver import build_ir
from forgecompile.ir.function import Module
from forgecompile.ir.interpreter import IRInterpreter
from forgecompile.ir.parser import parse_module
from forgecompile.ir.printer import format_module
from forgecompile.ml.features import feature_vector
from forgecompile.optimization.pass_manager import available_passes, optimize

ACTIONS: list[str] = sorted(available_passes())
STOP = "stop"
LABELS: list[str] = [*ACTIONS, STOP]
IMPROVEMENT_EPSILON = 1e-9  # relative improvement below this counts as "no improvement"


@dataclass(frozen=True)
class ProgramSpec:
    name: str
    source: str
    origin: str  # "generated", "benchmark" or "example"


@dataclass
class StateRecord:
    program: str
    origin: str
    step: int
    features: list[float]
    cost: float  # cost of this state
    initial_cost: float  # cost of the unoptimized program
    outcomes: dict[str, float]  # pass -> cost after applying it once
    taken: str  # action taken to reach the next state

    @property
    def label(self) -> str:
        best = min(ACTIONS, key=lambda a: (self.outcomes[a], a))
        gain = (self.cost - self.outcomes[best]) / self.cost if self.cost else 0.0
        return best if gain > IMPROVEMENT_EPSILON else STOP

    def gains(self) -> dict[str, float]:
        """Relative one-step improvement of each pass (negative = makes it worse)."""
        return {
            a: (self.cost - c) / self.cost if self.cost else 0.0 for a, c in self.outcomes.items()
        }


def clone_module(module: Module) -> Module:
    """Deep copy via the textual format; the print/parse round trip is tested to be exact."""
    return parse_module(format_module(module))


class CostEvaluator:
    """Memoized interpreter cost of a module."""

    def __init__(self, metric: str = "cost", max_steps: int = 50_000_000) -> None:
        if metric not in ("cost", "steps"):
            raise ValueError("metric must be 'cost' or 'steps'")
        self.metric = metric
        self.max_steps = max_steps
        self.cache: dict[str, float] = {}
        self.evaluations = 0

    def __call__(self, module: Module) -> float:
        key = hashlib.sha1(format_module(module).encode()).hexdigest()
        cached = self.cache.get(key)
        if cached is not None:
            return cached
        self.evaluations += 1
        result = IRInterpreter(module, self.max_steps).run()
        value = float(result.cost if self.metric == "cost" else result.steps)
        self.cache[key] = value
        return value


def apply_pass(module: Module, name: str) -> Module:
    """A new module: ``module`` with one pass applied (verified, so bugs surface loudly)."""
    copy = clone_module(module)
    optimize(copy, [name], verify=True)
    return copy


def trajectory(
    program: ProgramSpec,
    steps: int,
    epsilon: float,
    rng: random.Random,
    evaluator: CostEvaluator,
) -> list[StateRecord]:
    module = build_ir(program.source, program.name)
    initial = evaluator(module)
    records: list[StateRecord] = []
    for step in range(steps):
        cost = evaluator(module)
        results = {name: apply_pass(module, name) for name in ACTIONS}
        outcomes = {name: evaluator(m) for name, m in results.items()}
        record = StateRecord(
            program.name, program.origin, step, feature_vector(module), cost, initial, outcomes, ""
        )
        greedy = record.label
        if rng.random() < epsilon:
            chosen = rng.choice(ACTIONS)
        elif greedy == STOP:
            record.taken = STOP
            records.append(record)
            break  # no pass improves this state: the greedy walk ends here
        else:
            chosen = greedy
        record.taken = chosen
        records.append(record)
        module = results[chosen]
    return records


def generate_dataset(
    programs: list[ProgramSpec],
    steps: int = 8,
    epsilon: float = 0.3,
    seed: int = 0,
    metric: str = "cost",
    progress: Callable[[int, int], None] | None = None,
) -> list[StateRecord]:
    """State records for every program (sequentially; see ``scripts`` for parallel runs)."""
    rng = random.Random(seed)
    evaluator = CostEvaluator(metric)
    records: list[StateRecord] = []
    for i, program in enumerate(programs):
        records.extend(trajectory(program, steps, epsilon, rng, evaluator))
        if progress:
            progress(i + 1, len(programs))
    return records


def record_to_json(record: StateRecord) -> dict[str, object]:
    data = asdict(record)
    data["label"] = record.label
    return data


def record_from_json(data: dict[str, object]) -> StateRecord:
    features = data["features"]
    outcomes = data["outcomes"]
    assert isinstance(features, list) and isinstance(outcomes, dict)
    return StateRecord(
        program=str(data["program"]),
        origin=str(data["origin"]),
        step=int(str(data["step"])),
        features=[float(x) for x in features],
        cost=float(str(data["cost"])),
        initial_cost=float(str(data["initial_cost"])),
        outcomes={str(k): float(v) for k, v in outcomes.items()},
        taken=str(data["taken"]),
    )
